CREATE   VIEW [dbo].[ImportJSONFile_DATAQUALITYTHRESHOLDS]
AS
SELECT        [ExtractID], [id], [name], [critical_limit], [warning_limit], [created_by], [created_on]
FROM             WRKDQAPIUtilities.dbo.GETAPIRESULTS CROSS APPLY OPENJSON(GETRESULTS, N'$.data') WITH (id[nvarchar](50) '$.id', [name] [nvarchar](50) '$.name', critical_limit[nvarchar](50) '$.critical_limit', warning_limit[nvarchar](50) 
                         '$.warning_limit', created_by[nvarchar](50) '$.created_by', created_on[nvarchar](50) '$.created_on') AS r
WHERE        URLExtension = 'Data-Quality-Thresholds' AND NOT EXISTS
                             (SELECT        1
                               FROM            WRKDQAPIUtilities.dbo.JSON_DATAQUALITYTHRESHOLDS AS t
                               WHERE        t .ID = r.ID)
GO
