CREATE   VIEW [dbo].[ImportJSONFile_DATASETS]
AS
SELECT  
[ExtractID]
,[asset_id]
,[assigned_to]
,[field_count]
,[created_by]
,[created_on]
,[description]
,[id]
,[modified_by]
,[modified_on]
,[name]
,[purpose]
,[version]
