 [asset_id]		nvarchar(50) '$.asset_id'
,[assigned_to]	nvarchar(50) '$.assigned_to'
,[field_count]	nvarchar(50) '$.field_count'
,[created_by]	nvarchar(50) '$.created_by'
,[created_on]	nvarchar(50) '$.created_on'
,[description]	nvarchar(50) '$.description'
,[id]			nvarchar(50) '$.id'
,[modified_by]	nvarchar(50) '$.modified_by'
,[modified_on]	nvarchar(50) '$.modified_on'
,[name]			nvarchar(100) '$.name'
,[purpose]		nvarchar(50) '$.purpose'
,[version]		nvarchar(50) '$.version'
)
WHERE        URLExtension = 'Datasets'
GO
