CREATE   VIEW [dbo].[ImportJSONFile_DATASETS_CATEGORIES]
AS
SELECT        [ExtractID], TableID AS DatasetsID, ArrayValues AS Category
FROM             WRKDQAPIUtilities.dbo.GETAPIRESULTS CROSS APPLY OPENJSON(GETRESULTS, N'$.data') WITH (TableID NVARCHAR(50) '$.id', JSONArray NVARCHAR(max) '$.categories' AS JSON) AS r OUTER APPLY OPENJSON(JSONArray) 
                         WITH (ArrayValues NVARCHAR(50) '$') AS c
WHERE        URLExtension = 'Datasets' AND c.ArrayValues IS NOT NULL AND NOT EXISTS
                             (SELECT        1
                               FROM            WRKDQAPIUtilities.dbo.JSON_DATASETS_CATEGORIES AS t
                               WHERE        t .DatasetsID = r.TableID AND t .CATEGORIESID = c.ArrayValues)
GO
