CREATE VIEW [dbo].[ImportJSONFile_POLICIES]
AS
SELECT
    g.[ExtractID],
    p.[assigned_to],
    p.[asset_id],
    p.[created_by],
    p.[created_on],
    p.[criticality],
    p.[definition],
    p.[end_date],
    p.[id],
    p.[name],
    p.[purpose],
    p.[modified_by],
    p.[modified_on],
    p.[start_date],
    p.[type],
    p.[version],
    p.[review_status],
    p.[version_state]
FROM [dbo].[GETAPIRESULTS] AS g
CROSS APPLY OPENJSON(g.[GETRESULTS], N'$.data')
WITH
(
    [assigned_to]   nvarchar(100)  '$.assigned_to',
    [asset_id]      nvarchar(50)   '$.asset_id',
    [created_by]    nvarchar(100)  '$.created_by',
    [created_on]    nvarchar(50)   '$.created_on',
    [criticality]   nvarchar(50)   '$.criticality',
    [definition]    nvarchar(max)  '$.definition',
    [end_date]      nvarchar(50)   '$.end_date',
    [id]            nvarchar(100)  '$.id',
    [name]          nvarchar(2000) '$.name',
    [purpose]       nvarchar(max)  '$.purpose',
    [modified_by]   nvarchar(100)  '$.modified_by',
    [modified_on]   nvarchar(50)   '$.modified_on',
    [start_date]    nvarchar(50)   '$.start_date',
    [type]          nvarchar(100)  '$.type',
    [version]       int            '$.version',
    [review_status] nvarchar(50)   '$.review_status',
    [version_state] nvarchar(50)   '$.version_state'
) AS p
WHERE LOWER(g.[URLEXTENSION]) = 'policies'
--  AND ISJSON(g.[GETRESULTS]) = 1;
GO
