CREATE VIEW [dbo].[ImportJSONFile_POLICIES_CATEGORIES]
AS
SELECT
    g.[ExtractID],
    p.[PolicyID],
    c.[CategoryID] AS [Categories]
FROM [dbo].[GETAPIRESULTS] AS g
CROSS APPLY OPENJSON(g.[GETRESULTS], N'$.data')
WITH
(
    [PolicyID]      nvarchar(100) '$.id',
    [CategoriesJSON] nvarchar(max) '$.categories' AS JSON
) AS p
CROSS APPLY OPENJSON(p.[CategoriesJSON])
WITH
(
    [CategoryID] nvarchar(100) '$'
) AS c
WHERE LOWER(g.[URLEXTENSION]) = 'policies'
--  AND ISJSON(g.[GETRESULTS]) = 1
  AND c.[CategoryID] IS NOT NULL;
