CREATE VIEW [dbo].[ImportJSONFile_POLICIES_SPONSORS]
AS
SELECT
    g.[ExtractID],
    p.[PolicyID],
    s.[SponsorID] AS [Sponsors]
FROM [dbo].[GETAPIRESULTS] AS g
CROSS APPLY OPENJSON(g.[GETRESULTS], N'$.data')
WITH
(
    [PolicyID]    nvarchar(100) '$.id',
    [SponsorsJSON] nvarchar(max) '$.sponsors' AS JSON
) AS p
CROSS APPLY OPENJSON(p.[SponsorsJSON])
WITH
(
    [SponsorID] nvarchar(100) '$'
) AS s
WHERE LOWER(g.[URLEXTENSION]) = 'policies'
--  AND ISJSON(g.[GETRESULTS]) = 1
  AND s.[SponsorID] IS NOT NULL;
GO
