CREATE   VIEW [dbo].[ImportJSONFile_TERMS_RELATIONSHIPS]
AS
SELECT     [ExtractID], TableID AS TermID, ArrayValues AS [id], [type], direction, relationship
FROM        WRKDQAPIUtilities.dbo.GETAPIRESULTS CROSS APPLY 
OPENJSON(GETRESULTS, N'$.data') 
WITH(TableID NVARCHAR(50) '$.id', JSONArray NVARCHAR(max) '$.relationships' AS JSON) AS r CROSS APPLY 
OPENJSON(JSONArray) 
WITH (ArrayValues NVARCHAR(50) '$.id', [Type] nvarchar(200) '$.type', [Direction] nvarchar(50) '$.direction', [Relationship] nvarchar(50) '$.relationship') AS c       
WHERE     URLExtension = 'terms'  AND c.ArrayValues IS NOT NULL AND NOT EXISTS
                             (SELECT        1
                               FROM            WRKDQAPIUtilities.dbo.JSON_TERMS_RELATIONSHIPS AS t
                               WHERE        t .TermID = r.TableID AND t .id = c.ArrayValues)
GO
