/****** Object:  View [dbo].[APIResults_Combined_Backup_20260826]    Script Date: 11/25/2026 12:52:55 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



  
  
  
  
  
CREATE VIEW [dbo].[APIResults_Combined_Backup_20260826]  
AS  
  --SELECT * FROM JSON_USERS  
  --SELECT * FROM JSON_RULES  
  --select right(ttDQReportTracker.ReportName,(len(ttdqreporttracker.reportname)-11)),* from WRKDQOPS..ttDQReportTracker  
  --SELECT * FROM JSON_ENFORCEMENTS  
  --SELECT * FROM JSON_DATAQUALITYJOBS  
  --SELECT * FROM JSON_implementations  
  -- SELECT * FROM JSON_SYSTEMS   
  --SELECT * FROM JSON_CATEGORIES  
  --SELECT * FROM JSON_CATEGORIES_VALUES  
  --SELECT * FROM JSON_RULES_CATEGORIES  
  --SELECT * FROM JSN_OSUBJECT_AREAS  
  --SELECT JSON_RULES.* FROM JSON_RULE+'F  
  
--Pivot to obtain Categories per Column 
WITH CTE   
AS (  
  
 SELECT RuleID,[Dimension],[Criticality in Template],[Rule Typology],[SAP Table], [SAP Technical Field] ,[Data Domain Segment],[DataDomain],[Rule Type],[DQ Dimension]
 FROM  
 (  
  SELECT RULEID, value, name  
   FROM JSON_RULES_CATEGORIES AS Rule_Categories  
   LEFT OUTER JOIN   JSON_CATEGORIES_VALUES AS CategoryValue  
    ON Rule_Categories.CATEGORIES = CategoryValue.CATEGORYVALUEID  
   LEFT OUTER JOIN JSON_CATEGORIES AS Categories  
    ON Categories.CategoryID = CategoryValue.CATEGORYID  
   LEFT OUTER JOIN JSON_RULES AS Rules  
    ON id = Rule_Categories.RULEID  
 ) AS Source  
 PIVOT  
  ( max(value)  
   FOR NAME IN ([SAP Technical Field],[Dimension],[Criticality in Template],[Rule Typology],[SAP Table],[Data Domain Segment],[DataDomain],[Rule Type],[DQ Dimension])  
  ) AS PivotTable  
)  
  
  
SELECT DISTINCT DQJobs.ExtractID,  
    DQJobs.asset_id AS IMP_ID,  
    SUBSTRING(DQJobs.name,1,(CHARINDEX(' ',DQJobs.name)))  AS RollOut,  
    SubjectAreas.Name  AS Subject_Area,  
    DQJobs.name,  
	Replace(Replace(ENFS.name,'<p>',''),'</p>','') AS Enf_Name,
    REPLACE(REPLACE(Rules.implication,'<p>',''),'</p>','') AS Implication,  
    DQJobs.Description,  
    DQJobs.enforcement_id AS ENF_int_ID,  
    DQJobs.rule_id AS RULE_int_ID,  
 --   IMPS.id AS IMP_int_ID,  
    CAST(DQJobs.data_quality_score AS NUMERIC(7,4)) AS data_quality_score,  
  Results.LEROpportunityCount AS OpportunityCount,  
  Results.LERErrorCount AS ErrorCount,  
  Results.LERStatus AS Execution_Status,  
  Results.LERCompletedAt AS CompletedAt,  
    ENFS.enforcement_type,  
    ENFS.enforcement_system,  
    Systems.name AS System_name,  
    Systems.description AS System_Description,  
    Rules.asset_id AS Rule_ID,  
    Categories.Dimension,  
    categories.[Criticality in Template],  
    Categories.[Rule Typology],  
    Categories.[SAP Table],  
    Categories.[SAP Technical Field], 
	Categories.[Data Domain Segment],
	Categories.[DataDomain],
	Categories.[Rule Type],
	Categories.[DQ Dimension],
  CONCAT(Rules.asset_ID,'_',ENFs.asset_id,'_', DQJobs.asset_id) AS TabName,  
  Sprint,  
   CAST(getdate() AS DATE ) AS LoadDate,
   ENFs.roll_up_data_quality_score
  
 FROM JSON_DATAQUALITYJOBS AS DQJobs         --Data-quality-jobs  
 --LEFT OUTER JOIN JSON_DATAQUALITYJOBS_IMPLEMENTATION AS DQJobImp  --Implementations  
 -- ON DQJobs.id = DQJobImp.DQJobsID  
 LEFT OUTER JOIN JSON_IMPLEMENTATIONS AS IMPs      --Implementations  
  ON DQJobs.name = IMPs.name     
 LEFT OUTER JOIN JSON_DATAQUALITYJOBS_LATESTEXECUTIONRESULTS AS Results  
  ON DQJobs.id = Results.DQJobsID  
  -- Adding extra filter to consider several ExtractIDs and keep 1-1 Cardinality  
  AND DQJobs.ExtractID = Results.ExtractID  
 LEFT OUTER JOIN JSON_ENFORCEMENTS AS ENFs       --Enforcements  
  ON ENFS.id = DQJobs.enforcement_id          
 LEFT OUTER JOIN JSON_SYSTEMS AS Systems        --Systems  
  ON ENFs.enforcement_system = Systems.id         
 LEFT OUTER JOIN JSON_RULES AS Rules         --Rules  
  ON DQJobs.rule_id = Rules.id  
 LEFT OUTER JOIN CTE AS Categories    --Categories  
  ON Rules.id = Categories.RULEID  
 LEFT OUTER JOIN JSON_SUBJECTAREAS AS SubjectAreas    -- Subject Areas  
  ON Rules.Subject_area = SubjectAreas.ID  
 LEFT OUTER JOIN WRKDQOPS..ttDQReportTracker  
  ON DQJobs.name = ttDQReportTracker.ReportName  
 WHERE SubjectAreas.Name <> 'Target Model Data Profiling'   AND SubjectAreas.Name <> 'Finance - Record To Report (RTR)'
 -- AND DQJobs.ExtractID = 'DataQuality'  
 AND roll_up_data_quality_score = 1
  
GO
