CREATE   VIEW [dbo].[ImportJSONFile_VISIONS_SUPPORTINGDOCUMENTATION]
AS
SELECT     [ExtractID], TableID AS VisionsID, ArrayValues AS [name], [value]
FROM        WRKDQAPIUtilities.dbo.GETAPIRESULTS CROSS APPLY 
OPENJSON(GETRESULTS, N'$.data') 
WITH(TableID NVARCHAR(50) '$.id', JSONArray NVARCHAR(max) '$.supporting_documentation' AS JSON) AS r CROSS APPLY 
OPENJSON(JSONArray) 
WITH (ArrayValues NVARCHAR(50) '$.name', [value] nvarchar(200) '$.value') AS c       
WHERE     URLExtension = 'visions'  AND c.ArrayValues IS NOT NULL AND NOT EXISTS
                             (SELECT        1
                               FROM            WRKDQAPIUtilities.dbo.JSON_VISIONS_SUPPORTINGDOCUMENTATION AS t
                               WHERE        t .VisionsID = r.TableID AND t .name = c.ArrayValues)
