CREATE VIEW [dbo].[APIResults_DQScore_Weekly_Summary_PM0]
AS

-- Manually added record 1: Finance Master - 2026_32
SELECT 
    '2026_32' AS WeekID,
    'Finance Master' AS Subject_Area,
    16 AS NumberOfRules,
    3456 AS TotalErrorCount,
    181895 AS TotalOpportunityCount,
    CAST(0.9812 AS NUMERIC(7,4)) AS DQScore

UNION ALL
-- Manually added record 2: Finance Master - 2026_33
SELECT 
    '2026_33' AS WeekID,
    'Finance Master' AS Subject_Area,
    18 AS NumberOfRules,
    3888 AS TotalErrorCount,
    204442 AS TotalOpportunityCount,
    CAST(0.9812 AS NUMERIC(7,4)) AS DQScore

UNION ALL
-- Manually added record 3: Business Partners Master - 2026_32
SELECT 
    '2026_32' AS WeekID,
    'Business Partners Master' AS Subject_Area,
    6 AS NumberOfRules,
    147493 AS TotalErrorCount,
    820146 AS TotalOpportunityCount,
    CAST(0.8201 AS NUMERIC(7,4)) AS DQScore

UNION ALL
-- Manually added record 4: Business Partners Master - 2026_33
SELECT 
    '2026_33' AS WeekID,
    'Business Partners Master' AS Subject_Area,
    17 AS NumberOfRules,
    119654 AS TotalErrorCount,
    657202 AS TotalOpportunityCount,
    CAST(0.8173 AS NUMERIC(7,4)) AS DQScore


UNION 
SELECT 
    CONCAT(WeekYear, '_', WeekNumber) AS WeekID,
    Subject_Area,
    --WeekNumber,
    --WeekYear,
    COUNT(DISTINCT RULE_int_ID) AS NumberOfRules,
  --  COUNT(DISTINCT ExtractID) AS NumberOfExtracts,
    COALESCE(SUM(ErrorCount), 0) AS TotalErrorCount,
   COALESCE(SUM(OpportunityCount), 0) AS TotalOpportunityCount,
    CASE 
        WHEN COALESCE(SUM(OpportunityCount), 0) = 0 THEN NULL
        ELSE CAST(
            1 - CAST(COALESCE(SUM(ErrorCount), 0) AS NUMERIC(10,2)) / 
            CAST(SUM(OpportunityCount) AS NUMERIC(10,2))
            AS NUMERIC(7,4)
        ) 
    END AS DQScore--,
   -- MIN(CapturedDate) AS FirstCapturedDate,
   -- MAX(CapturedDate) AS LastCapturedDate
FROM 
    [dbo].[APIResults_Combined_History]
WHERE 
    name LIKE '%- PM0 -%'
    AND Subject_Area IS NOT NULL
    AND OpportunityCount > 0
    AND ErrorCount IS NOT NULL
GROUP BY 
    WeekNumber,
    WeekYear,
    Subject_Area;
GO
