/****** Object:  View [dbo].[APIResults_DQRule_Weekly_Changes]    Script Date: 11/25/2026 12:52:55 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   VIEW [dbo].[APIResults_DQRule_Weekly_Changes]
AS
WITH AvailableWeeks AS
(
    /*
        Get each available year/week combination and rank the weeks
        from newest to oldest.
    */
    SELECT
        WeekYear,
        WeekNumber,
        DENSE_RANK() OVER
        (
            ORDER BY
                WeekYear DESC,
                WeekNumber DESC
        ) AS WeekRank
    FROM
    (
        SELECT DISTINCT
            WeekYear,
            WeekNumber
        FROM [dbo].[APIResults_Combined_History]
        WHERE WeekYear IS NOT NULL
          AND WeekNumber IS NOT NULL
    ) AS DistinctWeeks
),
LatestWeek AS
(
    SELECT
        WeekYear,
        WeekNumber
    FROM AvailableWeeks
    WHERE WeekRank = 1
),
PreviousWeek AS
(
    SELECT
        WeekYear,
        WeekNumber
    FROM AvailableWeeks
    WHERE WeekRank = 2
),
LatestWeekRules AS
(
    /*
        DISTINCT prevents the same rule from appearing multiple times
        because of different executions or related history records.
    */
    SELECT DISTINCT
        H.Subject_Area,
        H.name,
        H.Rule_ID,
        H.[DQ Dimension],
        H.[DataDomain],
        H.[Data Domain Segment],
        H.[Criticality in Template],
        H.WeekYear,
        H.WeekNumber
    FROM [dbo].[APIResults_Combined_History] AS H
    INNER JOIN LatestWeek AS W
        ON  H.WeekYear = W.WeekYear
        AND H.WeekNumber = W.WeekNumber
    WHERE H.Subject_Area IS NOT NULL
      AND H.name IS NOT NULL
),
PreviousWeekRules AS
(
    SELECT DISTINCT
        H.Subject_Area,
        H.name,
        H.Rule_ID,
        H.[DQ Dimension],
        H.[DataDomain],
        H.[Data Domain Segment],
        H.[Criticality in Template],
        H.WeekYear,
        H.WeekNumber
    FROM [dbo].[APIResults_Combined_History] AS H
    INNER JOIN PreviousWeek AS W
        ON  H.WeekYear = W.WeekYear
        AND H.WeekNumber = W.WeekNumber
    WHERE H.Subject_Area IS NOT NULL
      AND H.name IS NOT NULL
)
SELECT
    COALESCE(CurrentRules.Subject_Area, PreviousRules.Subject_Area)
        AS Subject_Area,

    COALESCE(CurrentRules.name, PreviousRules.name)
        AS name,

    COALESCE(CurrentRules.Rule_ID, PreviousRules.Rule_ID)
        AS Rule_ID,

    CASE
        WHEN PreviousRules.name IS NULL THEN 'New'
        WHEN CurrentRules.name IS NULL THEN 'No Longer Showing'
    END AS Change_Type,

    PreviousRules.WeekYear
        AS Previous_WeekYear,

    PreviousRules.WeekNumber
        AS Previous_WeekNumber,

    CurrentRules.WeekYear
        AS Current_WeekYear,

    CurrentRules.WeekNumber
        AS Current_WeekNumber,

    COALESCE(
        CurrentRules.[DQ Dimension],
        PreviousRules.[DQ Dimension]
    ) AS [DQ Dimension],

    COALESCE(
        CurrentRules.[DataDomain],
        PreviousRules.[DataDomain]
    ) AS [DataDomain],

    COALESCE(
        CurrentRules.[Data Domain Segment],
        PreviousRules.[Data Domain Segment]
    ) AS [Data Domain Segment],

    COALESCE(
        CurrentRules.[Criticality in Template],
        PreviousRules.[Criticality in Template]
    ) AS [Criticality in Template]

FROM LatestWeekRules AS CurrentRules
FULL OUTER JOIN PreviousWeekRules AS PreviousRules
    ON  CurrentRules.Subject_Area = PreviousRules.Subject_Area
    AND CurrentRules.name = PreviousRules.name

WHERE CurrentRules.name IS NULL
   OR PreviousRules.name IS NULL;
GO
