CREATE VIEW [dbo].[APIReportOutput] AS
SELECT Rule_ID
	,IMP_ID
	,Subject_Area
	,trim(replace(replace(Enf_name, 'ENF - ', ''), 'Target Model Data Profiling -', '')) AS Enf_name
	,name
	,SUBSTRING(name, CHARINDEX('DQOpsId ', name) + 8, 4) AS DQOpsID
	,ReportType
	,data_quality_score
	,OpportunityCount
	,ErrorCount
	,CompletedAt
FROM [APIResults_Combined]
LEFT OUTER JOIN WRKDQOps..ttDQReportTracker ON DQOPSID = SUBSTRING(name, CHARINDEX('DQOpsId ', name) + 8, 4)
WHERE subject_area = 'Target Model Data Profiling'
