/****** Object:  View [dbo].[SubjectAreaDQScore]    Script Date: 11/25/2026 12:52:55 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

  CREATE VIEW [dbo].[SubjectAreaDQScore] AS
SELECT 
    Subject_Area AS [Subject Area], 
	CAST(1 - (CAST(SUM(ErrorCount) AS FLOAT) / CAST(SUM(OpportunityCount) AS FLOAT)) AS NUMERIC(7,4)) AS [DQ Score],
    COUNT(1) AS [DQ Rules]
FROM [APIResults_Combined_P00]
WHERE [Rule type] =  'Error'-- AND name like '%P00%'-- name not like '%0036%' and name not like '%0037%'and name not like '%0038%'
GROUP BY Subject_Area
GO
/****** Object:  View [dbo].[Top5Reports]    Script Date: 11/25/2026 12:52:55 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


  CREATE  VIEW [dbo].[Top5Reports] AS

  WITH CTE AS (
  SELECT 
    ROW_NUMBER() OVER(PARTITION BY Subject_Area, [Data Domain Segment] ORDER BY ERRORCOUNT DESC) as TopN,
    Subject_Area, 
    name,
    LTRIM(
      REPLACE(
        REPLACE(
          REPLACE(name, 'IMP - ', ''),
          'IMP- ', ''),
        'IMP-', '')
    ) AS name_cleaned,
    data_quality_score, 
    OpportunityCount, 
    errorcount, 
    DataDomain,  
    [Rule Type], 
    [Data Domain Segment]
  FROM [APIResults_Combined_P00]
  WHERE data_quality_score IS NOT NULL AND [Rule Type] = 'Error' --and name like '%P00%'
)
SELECT 
  CTE.TopN,
  CTE.Subject_Area, 
  CTE.name_cleaned as name,
  CTE.data_quality_score, 
  CTE.OpportunityCount, 
  CTE.errorcount, 
  CTE.DataDomain,  
  CTE.[Rule Type], 
  CTE.[Data Domain Segment],
  A.[DQ Dimension]
FROM CTE
INNER JOIN APIResults_Combined AS A ON
  CTE.name = A.name
WHERE CTE.TopN < 6
GO
/****** Object:  View [dbo].[DashboardSubjectAreaDQScore]    Script Date: 11/25/2026 12:52:55 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

  CREATE VIEW [dbo].[DashboardSubjectAreaDQScore] AS
  SELECT Subject_Area,[Data Domain Segment],  AVG(data_quality_score) as [DQ Score], sum(ErrorCount) As ErrorCount, sum(OpportunityCount) AS OpportunityCount
  FROM [APIResults_Combined]
  --WHERE data_quality_score <> 0 --and Subject_Area = 'Finance Master'
  GROUP BY Subject_Area, [Data Domain Segment]
GO
/****** Object:  View [dbo].[DashboardDataDomainDQScore]    Script Date: 11/25/2026 12:52:55 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



  CREATE VIEW [dbo].[DashboardDataDomainDQScore] AS
  WITH CTE AS (
  SELECT 
		Subject_Area AS [Subject Area], 
		[Data Domain Segment], 
		CAST(1 - (CAST(SUM(ErrorCount) AS FLOAT) / CAST(SUM(OpportunityCount) AS FLOAT)) AS NUMERIC(7,4)) AS [DQ Score],
		 sum(ErrorCount) As ErrorCount, 
		 sum(OpportunityCount) AS OpportunityCount,
		 count(1) as [DQ Rules]
  FROM [APIResults_Combined_P00]
  WHERE  [Rule type] =  'Error'-- AND name like '%P00%'--name like '%P00%' and name not like '%0036%'and name not like '%0037%'and name not like '%0038%'-- data_quality_score <> 0 --and Subject_Area = 'Finance Master'
  GROUP BY Subject_Area, [Data Domain Segment]
  )
  SELECT *, 
  CASE WHEN [DQ Score] >= 0.95
		THEN 'faCircleCheck'
		WHEN [DQ Score] >= 0.7 AND [DQ Score] < 0.95
		THEN 'faCircleExclamation'
		WHEN [DQ Score] < 0.7
		THEN 'faCircleXMark'
		END AS Icon
  FROM CTE

GO
