/****** Object:  View [dbo].[DashboardDataDomainDQScore_PM0]    Script Date: 11/25/2026 12:52:55 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



  CREATE VIEW [dbo].[DashboardDataDomainDQScore_PM0] AS
  SELECT 
		Subject_Area AS [Subject Area], 
		[Data Domain Segment], 
		CAST(1 - (CAST(SUM(ErrorCount) AS FLOAT) / CAST(SUM(OpportunityCount) AS FLOAT)) AS NUMERIC(7,4)) AS [DQ Score],
		 sum(ErrorCount) As ErrorCount, 
		 sum(OpportunityCount) AS OpportunityCount,
		 count(1) as [DQ Rules]
  FROM [APIResults_Combined_PM0]
  WHERE  [Rule type] =  'Error' --AND name like '%PM0%'-- data_quality_score <> 0 --and Subject_Area = 'Finance Master'
  GROUP BY Subject_Area, [Data Domain Segment]
GO
