CREATE VIEW [dbo].[DQAPIEnforcementsImpsRollOut_View]
AS

SELECT DISTINCT 
	   Rules.asset_id AS Rule_ID,
	   REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(ENFs.name,'<p>',''),'</p>',''),'<span>',''),'</span>',''),'&nbsp;','') AS [Name],
	   REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(ENFs.specification,'<p>',''),'</p>',''),'<span>',''),'</span>',''),'&nbsp;','') AS [Specification],
	   ENFs.enforcement_type AS [Type],
	   ENFs.enforcement_priority AS [Priority],
	   ENFs.enforcement_status AS [Status],
	    CASE WHEN ENFs.roll_up_data_quality_score = 1
			THEN 'TRUE'
			ELSE 'FALSE'  
		END AS [Roll Up DQ Score],
	   ISNULL(Users_req.email,'') AS Requester,
	   ISNULL(Users_impl.email,'') AS Implementer,
	   Systems.name AS [Enforcement System],
	   DQJobs.name AS [Implementation Name],
	   REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(DQJobs.Description,'<p>',''),'</p>',''),'<span>',''),'</span>',''),'&nbsp;','') AS [Description],
	   ISNULL(Users_imp_imp.email,'') AS [Implementation Implementer],
	   IMPs.method AS [Implmenetation Method],
	   '' AS [Implementation State], -- To be Confirmed
	   	   CASE WHEN DQJobs.save_report = 1
			THEN 'TRUE'
			ELSE 'FALSE'  
		END AS [Implementation Save Report],
		'TRUE' AS [Include DQ Report],
	   DataStores.name AS DataStore,
	   ImplCode.ErrorQuery AS [CDQ Error Query],
	   ImplCode.OpportunityQuery AS [CDQ Opportunity Error Query]
	  	FROM JSON_DATAQUALITYJOBS AS DQJobs								 --Data-quality-jobs
	LEFT OUTER JOIN JSON_DATAQUALITYJOBS_IMPLEMENTATION AS DQJob_Imp
		ON DQJobs.id = DQJob_Imp.DQJobsID
			AND DQJobs.ExtractID = DQJob_Imp.ExtractID
	LEFT OUTER JOIN JSON_IMPLEMENTATIONS AS IMPs					 --Implementations
		ON DQJob_Imp.ImplementationID= IMPs.id
			AND DQJob_Imp.ExtractID = IMPs.ExtractID	
	LEFT OUTER JOIN JSON_IMPLEMENTATIONS_CLOUDDATAQUALITY AS ImplCode --Implementation Code
		ON ImplCode.ImplementationID = DQJob_Imp.ImplementationID
			AND DQJob_Imp.ExtractID = ImplCode.ExtractID
	LEFT OUTER JOIN JSON_DATAQUALITYJOBS_LATESTEXECUTIONRESULTS AS Results
		ON DQJobs.id = Results.DQJobsID
			AND DQJobs.ExtractID = Results.ExtractID
	LEFT OUTER JOIN JSON_ENFORCEMENTS AS ENFs						 --Enforcements
		ON ENFS.id = DQJobs.enforcement_id	
			AND DQJobs.ExtractID = ENFs.ExtractID 
	LEFT OUTER JOIN JSON_SYSTEMS AS Systems							 --Systems
		ON ENFs.enforcement_system = Systems.id		
			AND ENFs.ExtractID = Systems.ExtractID
	LEFT OUTER JOIN JSON_RULES AS Rules								 --Rules
		ON DQJobs.rule_id = Rules.id
			AND DQJobs.ExtractID = Rules.ExtractID
	LEFT OUTER JOIN JSON_USERS as Users_req								-- Users_req
		ON ENFs.requester_id = Users_req.id
			AND ENFs.ExtractID = Users_req.ExtractID
	LEFT OUTER JOIN JSON_USERS as Users_impl								-- Users_impl
		ON ENFs.implementer_id = Users_impl.id
			AND ENFs.ExtractID = Users_impl.ExtractID
	LEFT OUTER JOIN JSON_USERS as Users_imp_imp								-- Users_imp_imp
		ON DQJobs.assigned_to = Users_imp_imp.id
			AND DQJobs.ExtractID = Users_imp_imp.ExtractID
	LEFT OUTER JOIN JSON_DATASTORES AS DataStores
		ON DQJobs.datastore_id = DataStores.ID
			AND DQJobs.ExtractID = DataStores.ExtractID
	LEFT OUTER JOIN JSON_SUBJECTAREAS AS SubjectAreas				-- Subject Areas
		ON Rules.Subject_area = SubjectAreas.ID
			AND Rules.ExtractID = SubjectAreas.ExtractID
		
	INNER JOIN DQAPIRulesRollOut_Select AS Selected ON 
		Rules.asset_id = Selected.Link_ID AND
		Selected = 1
	WHERE DataStores.id IS NOT NULL
		AND SubjectAreas.Name <> 'Template - Test Subject Area'
		AND DQJobs.ExtractID = 'Roll-Out'

GO
