                         [data_quality_score] [nvarchar](50) '$.data_quality_score', [enforcement_priority] nvarchar(50) '$.enforcement_priority', [requester_id] nvarchar(50) '$.requester_id', [implementer_id] [nvarchar](50) 
                         '$.implementer_id', [enforcement_status] [nvarchar](50) '$.enforcement_status', [enforcement_type] [nvarchar](50) '$.enforcement_type', [enforcement_system] [nvarchar](50) '$.enforcement_system', 
