CREATE VIEW [dbo].[DQAPIRulesRollOut_Select_View]
AS
		
SELECT DISTINCT 0 AS [Selected],
	   Rules.asset_id AS [Link_ID],
	   SubjectAreas.Name  AS Subject_Area,
	   Rules.statement AS [Rule],
	   REPLACE(REPLACE(Rules.implication,'<p>',''),'</p>','') AS Implication,
	   '' AS [Additional Information],
	   Rules.data_quality_threshold_id AS [DQ_Threshold],
	   Users.email,
	   CASE WHEN Rules.version_state = 'Published'
			THEN 'TRUE'
			ELSE 'FALSE'
	   END AS [Auto Publish],
	   CAST(getdate() AS DATE )  as ImportDate
	FROM JSON_RULES AS Rules								 --Rules
	LEFT OUTER JOIN JSON_SUBJECTAREAS AS SubjectAreas				-- Subject Areas
		ON Rules.Subject_area = SubjectAreas.ID
	LEFT OUTER JOIN JSON_USERS AS Users
		ON Rules.assigned_to  = USERS.id
	WHERE SubjectAreas.Name <> 'Template - Test Subject Area'
		AND Rules.ExtractID = 'Roll-Out'
	
GO
/****** Object:  View [dbo].[Top5Reports_PM0]    Script Date: 11/25/2026 12:52:55 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO







  CREATE  VIEW [dbo].[Top5Reports_PM0] AS

  WITH CTE AS (
  SELECT 
    ROW_NUMBER() OVER(PARTITION BY Subject_Area, [Data Domain Segment] ORDER BY ErrorCount DESC) as TopN,
    Subject_Area, 
    name,
    LTRIM(
      REPLACE(
        REPLACE(
          REPLACE(name, 'IMP - ', ''),
          'IMP- ', ''),
        'IMP-', '')
    ) AS name_cleaned,
    data_quality_score, 
    OpportunityCount, 
    errorcount, 
    DataDomain,  
    [Rule Type], 
    [Data Domain Segment]
  FROM [APIResults_Combined_PM0]
  WHERE data_quality_score IS NOT NULL AND [Rule Type] = 'Error'-- and name like '%PM0%'
)
SELECT 
  CTE.TopN,
  CTE.Subject_Area, 
  CTE.name_cleaned as name,
  CTE.data_quality_score, 
  CTE.OpportunityCount, 
  CTE.errorcount, 
  CTE.DataDomain,  
  CTE.[Rule Type], 
  CTE.[Data Domain Segment],
  A.[DQ Dimension]
FROM CTE
INNER JOIN APIResults_Combined AS A ON
  CTE.name = A.name
WHERE CTE.TopN < 6
GO
