CREATE   VIEW [dbo].[ImportJSONFile_COMPONENTS_TYPE_COUNTS]
AS
SELECT        [ExtractID], TableID AS SystemID, JSONArray AS [name], ArrayValues AS [value]
FROM            WRKDQAPIUtilities.dbo.GETAPIRESULTS_ID CROSS APPLY OPENJSON(GETRESULTS, N'$.data') 
				WITH (TableID NVARCHAR(50) '$.id', JSONArray NVARCHAR(max) '$.name' AS JSON) AS r OUTER 
                         APPLY OPENJSON(JSONArray) WITH (ArrayValues NVARCHAR(50) '$.value') AS c
WHERE        TABLENAME= 'COMPONENTS' AND c.ArrayValues IS NOT NULL AND NOT EXISTS
                             (SELECT        1
                               FROM            WRKDQAPIUtilities.dbo.JSON_COMPONENTS_TYPE_COUNTS AS t
                               WHERE        t.SystemID = r.TableID AND t.value = c.ArrayValues)
GO
