CREATE   VIEW [dbo].[ImportJSONFile_DATAQUALITYJOBS]
AS
SELECT DISTINCT       [ExtractID], id, [version], asset_id, name, description, enforcement_id, agent_id, connection_id, rule_id, system_id, assigned_to, data_quality_score, data_quality_threshold_id, save_report, visible, ALTERd_by, ALTERd_on, modified_by, 
                         modified_on, datastore_id
FROM            WRKDQAPIUtilities.dbo.GETAPIRESULTS CROSS APPLY OPENJSON(GETRESULTS, N'$.data') WITH (id nvarchar(50) '$.id', [version] nvarchar(50) '$.version', asset_id nvarchar(50) '$.asset_id', name nvarchar(2000) '$.name', 
                         description nvarchar(2000) '$.description', enforcement_id nvarchar(50) '$.enforcement_id', agent_id nvarchar(50) '$.agent_id', connection_id nvarchar(50) '$.connection_id', rule_id nvarchar(50) '$.rule_id', 
                         system_id nvarchar(50) '$.system_id', assigned_to nvarchar(50) '$.assigned_to', data_quality_score nvarchar(50) '$.data_quality_score', data_quality_threshold_id nvarchar(50) '$.data_quality_threshold_id', 
                         save_report bit '$.save_report', visible bit '$.visible', ALTERd_by nvarchar(50) '$.ALTERd_by', ALTERd_on nvarchar(50) '$.ALTERd_on', modified_by nvarchar(50) '$.modified_by', modified_on nvarchar(50) 
                         '$.modified_on', datastore_id nvarchar(50) '$.datastore_id')
WHERE        URLExtension = 'Data-Quality-Jobs'
AND ISJSON(GETRESULTS) = 1;
GO
