CREATE   VIEW [dbo].[ImportJSONFile_DATAQUALITYJOBS_LATESTEXECUTIONRESULTS]
AS
SELECT DISTINCT       [ExtractID], TableID AS DQJobsID, Status, OpportunityCount, ErrorCount, CompletedAt
FROM            WRKDQAPIUtilities.dbo.GETAPIRESULTS CROSS APPLY OPENJSON(GETRESULTS, N'$.data') WITH (TableID NVARCHAR(50) '$.id', JSONArray NVARCHAR(max) '$.latest_execution_result' AS JSON) AS r OUTER 
                         APPLY OPENJSON(JSONArray) WITH (ArrayValues NVARCHAR(50) '$', Status nvarchar(2000) '$.status', OpportunityCount nvarchar(20) '$.opportunity_count', ErrorCount int '$.error_count', 
                         CompletedAt date '$.completed_at') AS c
WHERE        URLExtension = 'data-quality-jobs' AND NOT EXISTS
                             (SELECT        1
                               FROM            WRKDQAPIUtilities.dbo.JSON_DATAQUALITYJOBS_LATESTEXECUTIONRESULTS AS t
                               WHERE        t.DQJobsID = r.TableID
							   AND t.[ExtractID] = GETAPIRESULTS.[ExtractID]
							   )
			AND ISJSON(GETRESULTS) = 1;
				
GO
