 CREATE   PROCEDURE [dbo].[API_DQReportDetail_Ins] 
AS
DECLARE @SQLquery nvarchar(max)
DECLARE @DQTable nvarchar(max)
DECLARE @CompletedAt nvarchar(max)

--TRUNCATE TABLE DQReportDetail

DECLARE cursor1 cursor for
/*-------- GET LIST OF REPORT OUTPUTS ------------------------------------------------------------------------------------------------*/
/*-------- Since historic data is required removed TRUNCATE from DQReportDetail and pointing cursor to view with latest data. --------*/
SELECT  tabname, CompletedAt from APIResults_Combined
-- Adding extra filter to avoid DQFailedData queries for rules that used to have errors and now are empty (this does not truncate on DQFailedData)
WHERE ISNULL(ErrorCount,'') <> '0'
--where rule_int_id = 'rul_M3t9KdqcHXtGRYvATRvcBA9FuKP'

OPEN cursor1
FETCH NEXT FROM cursor1 INTO @dqtable, @completedAt
while @@FETCH_STATUS = 0
BEGIN
--PRINT(@DQTable)
--PRINT(@COMPLETEDAT)
SET @sqlquery = '
IF EXISTS (SELECT TOP 1 * FROM DQFailedData.sys.tables WHERE name = ''' +@DQTable + ''' ) BEGIN  INSERT INTO DQReportDetail (TABNAME, LIFNR, CompletedAt, LoadDate)
( SELECT ''' +@DQTable +''', LIFNR, '''+@CompletedAt+ ''', CAST(getDate() AS Date) AS LoadDate FROM DQFailedData.dbo.'+@DQTable + ') END'

--PRINT(@SQLQUERY)
exec sp_executesql @sqlquery
FETCH NEXT FROM cursor1 INTO @dqtable, @Completedat
END
CLOSE cursor1
DEALLOCATE cursor1

--SELECT * FROM DQReportDetail
--TRUNCATE TABLE DQReportDetail
--EXEC [API_DQReportDetail_Ins]
GO
