   CREATE   PROCEDURE [dbo].[DQReportsGeneralData_Ins] 
	
AS


DECLARE @ExtractID NVARCHAR(50) = 'TEST'; 
DECLARE @ProcessWeek INT = DATEPART(WEEK, GETDATE());
DECLARE @ProcessYear INT = DATEPART(YEAR, GETDATE());

--SELECT * FROM GETAPIRESULTS

/*---Call APIs and extract all data----*/ 
EXEC webKnowledgeTierExtract_GETAPIRESULTS_GETRESULTS_TABLENAME_Upd 'rules', 'TEST'
EXEC webKnowledgeTierExtract_GETAPIRESULTS_GETRESULTS_TABLENAME_Upd 'TESTjobs', 'TEST'
EXEC webKnowledgeTierExtract_GETAPIRESULTS_GETRESULTS_TABLENAME_Upd 'enforcements', 'TEST'
EXEC webKnowledgeTierExtract_GETAPIRESULTS_GETRESULTS_TABLENAME_Upd 'implementations', 'TEST'
EXEC webKnowledgeTierExtract_GETAPIRESULTS_GETRESULTS_TABLENAME_Upd 'systems', 'TEST'
EXEC webKnowledgeTierExtract_GETAPIRESULTS_GETRESULTS_TABLENAME_Upd 'categories', 'TEST'
EXEC webKnowledgeTierExtract_GETAPIRESULTS_GETRESULTS_TABLENAME_Upd 'subjectareas', 'TEST'
EXEC webKnowledgeTierExtract_GETAPIRESULTS_GETRESULTS_TABLENAME_Upd 'policies', 'TEST'

/*-- Save and generate historical data --*/
INSERT INTO [dbo].[GETAPIRESULTS_History]
        (ExtractID, URL, URLEXTENSION, TENANTID, TABLENAME, GETRESULTS, 
         APIUsername, APIPassword, APIPassword_BAK, TableOrder, Active,
         LastUpdate, WeekNumber, WeekYear, CapturedDate)
    SELECT
        ExtractID,
        URL,
        URLEXTENSION,
        TENANTID,
        TABLENAME,
        GETRESULTS,
        APIUsername,
        APIPassword,
        APIPassword_BAK,
        TableOrder,
        Active,
        LastUpdate,
        DATEPART(WEEK, LastUpdate)  AS WeekNumber,
        DATEPART(YEAR, LastUpdate)  AS WeekYear,
        CAST(GETDATE() AS DATE)     AS CapturedDate
    FROM [dbo].[GETAPIRESULTS]
    -- Avoid duplicate weeks
    WHERE NOT EXISTS (
        SELECT 1 
        FROM [dbo].[GETAPIRESULTS_History] h
        WHERE h.ExtractID    = [GETAPIRESULTS].ExtractID
        AND   h.URLEXTENSION = [GETAPIRESULTS].URLEXTENSION
        AND   h.WeekNumber   = DATEPART(WEEK, [GETAPIRESULTS].LastUpdate)
        AND   h.WeekYear     = DATEPART(YEAR, [GETAPIRESULTS].LastUpdate)
    )


EXEC [dbo].[webKnowledgeTierExtract_ArchiveToHistory] @ExtractID = @ExtractID, @WeekNumber = @ProcessWeek, @WeekYear = @ProcessYear;


/*---Push extracted data into ---*/
