--      ,REPLACE(REPLACE([System_Description],'<p>',''),'</p>','') AS System_Description
--      ,[Rule_ID]
--      ,[Dimension]
--      ,[Criticality in Template]
--      ,[Rule Typology]
--      ,[SAP Table]
--      ,[SAP Technical Field]
--      ,[TabName]
--      ,[Sprint]
--      ,[LoadDate]
--	FROM APIResults_Combined
