/****** Object:  StoredProcedure [dbo].[webKnowledgeTierExtract_ArchiveToHistory]    Script Date: 11/25/2026 12:52:55 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[webKnowledgeTierExtract_ArchiveToHistory]
    @ExtractID NVARCHAR(50) = NULL,
    @WeekNumber INT = NULL,
    @WeekYear INT = NULL,
    @TableName NVARCHAR(255) = NULL
AS
BEGIN
    SET NOCOUNT ON;
 
    DECLARE @SourceTableName NVARCHAR(255);
    DECLARE @HistoryTableName NVARCHAR(255);
    DECLARE @InsertSQL NVARCHAR(MAX);
    DECLARE @SelectColumnList NVARCHAR(MAX);
    DECLARE @InsertColumnList NVARCHAR(MAX);
    DECLARE @CurrentWeek INT;
    DECLARE @CurrentYear INT;
    DECLARE @CapturedDate DATE;
 
    IF @WeekNumber IS NULL OR @WeekYear IS NULL
    BEGIN
        SET @CurrentWeek = DATEPART(WEEK, GETDATE());
        SET @CurrentYear = DATEPART(YEAR, GETDATE());
    END
    ELSE
    BEGIN
        SET @CurrentWeek = @WeekNumber;
        SET @CurrentYear = @WeekYear;
    END
 
    SET @CapturedDate = CAST(GETDATE() AS DATE);
 
    DECLARE TableCursor CURSOR FOR
        SELECT TABLE_NAME
        FROM INFORMATION_SCHEMA.TABLES
        WHERE TABLE_SCHEMA = 'dbo'
          AND TABLE_NAME LIKE 'JSON[_]%'
          AND TABLE_NAME NOT LIKE '%[_]History'
        ORDER BY TABLE_NAME;
 
    OPEN TableCursor;
    FETCH NEXT FROM TableCursor INTO @SourceTableName;
 
    WHILE @@FETCH_STATUS = 0
    BEGIN
        SET @HistoryTableName = @SourceTableName + '_History';
 
        SET @SelectColumnList = (
            SELECT STRING_AGG('[' + COLUMN_NAME + ']', ',')
            FROM INFORMATION_SCHEMA.COLUMNS
            WHERE TABLE_SCHEMA = 'dbo'
              AND TABLE_NAME = @SourceTableName
              AND COLUMNPROPERTY(OBJECT_ID(@SourceTableName), COLUMN_NAME, 'IsIdentity') = 0
        );
 
        SET @InsertColumnList = @SelectColumnList + ',[WeekNumber],[WeekYear],[CapturedDate]';
 
        -- Build INSERT with proper WHERE clause
        SET @InsertSQL =
            'INSERT INTO [dbo].[' + @HistoryTableName + '] (' +
            @InsertColumnList +
            ') SELECT ' +
            @SelectColumnList + ',' +
            CAST(@CurrentWeek AS VARCHAR(10)) + ',' +
            CAST(@CurrentYear AS VARCHAR(10)) + ',' +
            '''' + CAST(@CapturedDate AS NVARCHAR(10)) + ''' ' +
            'FROM [dbo].[' + @SourceTableName + '] ';
 
        -- Build WHERE clause - ExtractID filter FIRST, then NOT EXISTS
        IF @ExtractID IS NOT NULL AND EXISTS (
            SELECT 1
            FROM INFORMATION_SCHEMA.COLUMNS
            WHERE TABLE_SCHEMA = 'dbo'
              AND TABLE_NAME = @SourceTableName
              AND COLUMN_NAME = 'ExtractID'
        )
        BEGIN
            SET @InsertSQL = @InsertSQL +
                'WHERE [' + @SourceTableName + '].ExtractID = ''' + @ExtractID + ''' ' +
                'AND NOT EXISTS (SELECT 1 FROM [dbo].[' + @HistoryTableName + '] h ' +
                'WHERE h.WeekNumber = ' + CAST(@CurrentWeek AS VARCHAR(10)) +
                ' AND h.WeekYear = ' + CAST(@CurrentYear AS VARCHAR(10)) +
                ' AND h.ExtractID = ''' + @ExtractID + ''');';
        END
        ELSE
        BEGIN
            SET @InsertSQL = @InsertSQL +
                'WHERE NOT EXISTS (SELECT 1 FROM [dbo].[' + @HistoryTableName + '] h ' +
                'WHERE h.WeekNumber = ' + CAST(@CurrentWeek AS VARCHAR(10)) +
                ' AND h.WeekYear = ' + CAST(@CurrentYear AS VARCHAR(10)) + ');';
        END;
 
        BEGIN TRY
            EXEC sp_executesql @InsertSQL;
            PRINT '✓ ' + @HistoryTableName;
        END TRY
        BEGIN CATCH
            PRINT '✗ ' + @HistoryTableName + ': ' + ERROR_MESSAGE();
        END CATCH;
 
        FETCH NEXT FROM TableCursor INTO @SourceTableName;
    END;
 
    CLOSE TableCursor;
    DEALLOCATE TableCursor;
 
    PRINT 'Archive complete (' + CAST(@CurrentWeek AS VARCHAR(3)) + '/' + CAST(@CurrentYear AS VARCHAR(4)) + ')';
END;
GO
/****** Object:  StoredProcedure [dbo].[webKnowledgeTierExtract_ArchiveToHistory_DEBUG]    Script Date: 11/25/2026 12:52:55 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROCEDURE [dbo].[webKnowledgeTierExtract_ArchiveToHistory_DEBUG]
    @ExtractID NVARCHAR(50) = NULL,
    @WeekNumber INT = NULL,
    @WeekYear INT = NULL
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @SourceTableName NVARCHAR(255) = 'JSON_RULES';
    DECLARE @HistoryTableName NVARCHAR(255) = @SourceTableName + '_History';
    DECLARE @CurrentWeek INT = @WeekNumber;
    DECLARE @CurrentYear INT = @WeekYear;
    DECLARE @SelectColumnList NVARCHAR(MAX);
    DECLARE @InsertColumnList NVARCHAR(MAX);
    DECLARE @InsertSQL NVARCHAR(MAX);

    SET @SelectColumnList = (
        SELECT STRING_AGG('[' + COLUMN_NAME + ']', ',')
        FROM INFORMATION_SCHEMA.COLUMNS
        WHERE TABLE_SCHEMA = 'dbo'
          AND TABLE_NAME = @SourceTableName
          AND COLUMNPROPERTY(OBJECT_ID(@SourceTableName), COLUMN_NAME, 'IsIdentity') = 0
    );

    SET @InsertColumnList = @SelectColumnList + ',[WeekNumber],[WeekYear],[CapturedDate]';

    SET @InsertSQL =
        'INSERT INTO [dbo].[' + @HistoryTableName + '] (' +
        @InsertColumnList +
        ') SELECT ' +
        @SelectColumnList + ',' +
        CAST(@CurrentWeek AS VARCHAR(10)) + ',' +
        CAST(@CurrentYear AS VARCHAR(10)) + ',' +
        '''' + CAST(CAST(GETDATE() AS DATE) AS NVARCHAR(10)) + ''' ' +
        'FROM [dbo].[' + @SourceTableName + '] ' +
        'WHERE ExtractID = ''' + @ExtractID + ''' ' +
        'AND NOT EXISTS (SELECT 1 FROM [dbo].[' + @HistoryTableName + '] h ' +
        'WHERE h.WeekNumber = ' + CAST(@CurrentWeek AS VARCHAR(10)) +
        ' AND h.WeekYear = ' + CAST(@CurrentYear AS VARCHAR(10)) +
        ' AND h.ExtractID = ''' + @ExtractID + ''');';

    PRINT @InsertSQL;
    EXEC sp_executesql @InsertSQL;
END;

-- Test it
EXEC [dbo].[webKnowledgeTierExtract_ArchiveToHistory_DEBUG] @ExtractID = 'TEST', @WeekNumber = 34, @WeekYear = 2026;

-- Check history
SELECT WeekNumber, COUNT(*) FROM [dbo].[JSON_RULES_History] WHERE ExtractID = 'TEST' GROUP BY WeekNumber;
GO
/****** Object:  StoredProcedure [dbo].[webKnowledgeTierExtract_GETAPIRESULTS_GETRESULTS_TABLENAME_Upd]    Script Date: 11/25/2026 12:52:55 PM ******/
