/****** Object:  StoredProcedure [dbo].[webKnowledgeTierExtract_JSON_RULES_History_Ins]    Script Date: 11/25/2026 12:52:55 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROCEDURE [dbo].[webKnowledgeTierExtract_JSON_RULES_History_Ins]
    @ExtractID NVARCHAR(50)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @WeekNumber   INT;
    DECLARE @WeekYear     INT;
    DECLARE @CapturedDate DATE;

    /*
        Use the most recent rules extraction when more than one
        GETAPIRESULTS record exists for the same ExtractID.
    */
    SELECT TOP (1)
        @WeekNumber   = DATEPART(WEEK, [LastUpdate]),
        @WeekYear     = DATEPART(YEAR, [LastUpdate]),
        @CapturedDate = CAST([LastUpdate] AS DATE)
    FROM [dbo].[GETAPIRESULTS]
    WHERE [ExtractID] = @ExtractID
      AND [URLEXTENSION] = N'rules'
    ORDER BY [LastUpdate] DESC;

    /*
        Prevent inserts with NULL week/date values if the extract
        cannot be found in GETAPIRESULTS.
    */
    IF @CapturedDate IS NULL
    BEGIN
        THROW 51000,
              'No GETAPIRESULTS record was found for the supplied ExtractID with URLEXTENSION = rules.',
              1;
    END;

    BEGIN TRY
        BEGIN TRANSACTION;

        /* =========================================================
           Main rules history
           ========================================================= */

        DELETE FROM [dbo].[JSON_RULES_History]
        WHERE [ExtractID] = @ExtractID
          AND [WeekNumber] = @WeekNumber
          AND [WeekYear] = @WeekYear;

        INSERT INTO [dbo].[JSON_RULES_History]
        (
            [ExtractID],
            [asset_id],
            [assigned_to],
            [created_by],
            [created_on],
            [id],
            [implication],
            [additional_info],
            [modified_by],
            [modified_on],
            [relationships],
            [categories],
            [sponsors],
            [statement],
            [visible],
            [data_quality_score],
            [data_quality_threshold_id],
            [enforcements],
            [business_concepts],
            [directed_business_processes],
            [subject_area],
            [supporting_documentation],
            [review_status],
            [version_state],
            [version],
            [WeekNumber],
            [WeekYear],
            [CapturedDate]
        )
        SELECT
            [ExtractID],
            [asset_id],
            [assigned_to],
            [created_by],
            [created_on],
            [id],
            [implication],
            [additional_info],
            [modified_by],
            [modified_on],
            [relationships],
            [categories],
            [sponsors],
            [statement],
            [visible],
            [data_quality_score],
            [data_quality_threshold_id],
            [enforcements],
            [business_concepts],
            [directed_business_processes],
            [subject_area],
            [supporting_documentation],
            [review_status],
            [version_state],
            [version],
            @WeekNumber,
            @WeekYear,
            @CapturedDate
        FROM [dbo].[JSON_RULES]
        WHERE [ExtractID] = @ExtractID;


        /* =========================================================
           Business concepts history
           ========================================================= */

        DELETE FROM [dbo].[JSON_RULES_BUSINESSCONCEPTS_History]
        WHERE [ExtractID] = @ExtractID
          AND [WeekNumber] = @WeekNumber
          AND [WeekYear] = @WeekYear;

        INSERT INTO [dbo].[JSON_RULES_BUSINESSCONCEPTS_History]
        (
            [ExtractID],
            [RULEID],
            [BusinessConcepts],
            [WeekNumber],
            [WeekYear],
            [CapturedDate]
        )
        SELECT
            [ExtractID],
            [RULEID],
            [BusinessConcepts],
            @WeekNumber,
            @WeekYear,
            @CapturedDate
        FROM [dbo].[JSON_RULES_BUSINESSCONCEPTS]
        WHERE [ExtractID] = @ExtractID;


        /* =========================================================
           Categories history
           ========================================================= */

        DELETE FROM [dbo].[JSON_RULES_CATEGORIES_History]
        WHERE [ExtractID] = @ExtractID
          AND [WeekNumber] = @WeekNumber
          AND [WeekYear] = @WeekYear;

        INSERT INTO [dbo].[JSON_RULES_CATEGORIES_History]
        (
            [ExtractID],
            [RULEID],
            [CATEGORIES],
            [WeekNumber],
            [WeekYear],
            [CapturedDate]
        )
        SELECT
            [ExtractID],
            [RULEID],
            [CATEGORIES],
            @WeekNumber,
            @WeekYear,
            @CapturedDate
        FROM [dbo].[JSON_RULES_CATEGORIES]
        WHERE [ExtractID] = @ExtractID;


        /* =========================================================
           Directed business processes history
           ========================================================= */

        DELETE FROM [dbo].[JSON_RULES_DIRECTEDBUSINESSPROCESSES_History]
        WHERE [ExtractID] = @ExtractID
          AND [WeekNumber] = @WeekNumber
          AND [WeekYear] = @WeekYear;

        INSERT INTO [dbo].[JSON_RULES_DIRECTEDBUSINESSPROCESSES_History]
        (
            [ExtractID],
            [RULEID],
            [DirectedBusinessProcesses],
            [WeekNumber],
            [WeekYear],
            [CapturedDate]
        )
        SELECT
            [ExtractID],
            [RULEID],
            [DirectedBusinessProcesses],
            @WeekNumber,
            @WeekYear,
            @CapturedDate
        FROM [dbo].[JSON_RULES_DIRECTEDBUSINESSPROCESSES]
        WHERE [ExtractID] = @ExtractID;


        /* =========================================================
           Enforcements history
           ========================================================= */

        DELETE FROM [dbo].[JSON_RULES_ENFORCEMENTS_History]
        WHERE [ExtractID] = @ExtractID
          AND [WeekNumber] = @WeekNumber
          AND [WeekYear] = @WeekYear;

        INSERT INTO [dbo].[JSON_RULES_ENFORCEMENTS_History]
        (
            [ExtractID],
            [RULEID],
            [Enforcements],
            [WeekNumber],
            [WeekYear],
            [CapturedDate]
        )
        SELECT
            [ExtractID],
            [RULEID],
            [Enforcements],
            @WeekNumber,
            @WeekYear,
            @CapturedDate
        FROM [dbo].[JSON_RULES_ENFORCEMENTS]
        WHERE [ExtractID] = @ExtractID;


        /* =========================================================
           Relationships history
           ========================================================= */

        DELETE FROM [dbo].[JSON_RULES_RELATIONSHIPS_History]
        WHERE [ExtractID] = @ExtractID
          AND [WeekNumber] = @WeekNumber
          AND [WeekYear] = @WeekYear;

        INSERT INTO [dbo].[JSON_RULES_RELATIONSHIPS_History]
        (
            [ExtractID],
            [RULEID],
            [id],
            [type],
            [direction],
            [relationship],
            [WeekNumber],
            [WeekYear],
            [CapturedDate]
        )
        SELECT
            [ExtractID],
            [RULEID],
            [id],
            [type],
            [direction],
            [relationship],
            @WeekNumber,
            @WeekYear,
            @CapturedDate
        FROM [dbo].[JSON_RULES_RELATIONSHIPS]
        WHERE [ExtractID] = @ExtractID;


        /* =========================================================
           Supporting documentation history
           ========================================================= */

        DELETE FROM [dbo].[JSON_RULES_SUPPORTINGDOCUMENTATION_History]
        WHERE [ExtractID] = @ExtractID
          AND [WeekNumber] = @WeekNumber
          AND [WeekYear] = @WeekYear;

        INSERT INTO [dbo].[JSON_RULES_SUPPORTINGDOCUMENTATION_History]
        (
            [ExtractID],
            [RuleID],
            [name],
            [value],
            [WeekNumber],
            [WeekYear],
            [CapturedDate]
        )
        SELECT
            [ExtractID],
            [RuleID],
            [name],
            [value],
            @WeekNumber,
            @WeekYear,
            @CapturedDate
        FROM [dbo].[JSON_RULES_SUPPORTINGDOCUMENTATION]
        WHERE [ExtractID] = @ExtractID;


        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
        BEGIN
            ROLLBACK TRANSACTION;
        END;

        THROW;
    END CATCH;
END;
GO
/****** Object:  StoredProcedure [dbo].[webKnowledgeTierExtract_JSON_TABLES_Ins]    Script Date: 11/25/2026 12:52:55 PM ******/
SET ANSI_NULLS ON
GO
