GO

      
      
CREATE   PROCEDURE [dbo].[webKnowledgeTierExtract_JSON_TABLES_Ins]       
@InitializeTranslationTables nvarchar(50) = NULL, @ExtractID nvarchar(50), @TableName nvarchar(255)      
AS      
BEGIN      
DECLARE @TableNameGETAPI nvarchar(255)      
DECLARE @SQL nvarchar(255)      
      
set @TableNameGETAPI = @TableName      
      
declare cur CURSOR LOCAL for       
    Select Table_Name From WRKDQAPIUtilities.INFORMATION_SCHEMA.TABLES      
 Where TABLE_NAME not like '%AGENTS%'--AND TABLE_NAME <> 'JSON_AGENTS'
 AND TABLE_NAME NOT LIKE '%History'    
 AND (TABLE_NAME like '%JSON[_]'+@TableName      
 
 OR TABLE_NAME like '%JSON[_]'+@TableName+'[_]%' )     
 ORDER BY TABLE_NAME      
Open Cur;      
FETCH NEXT FROM cur into @TableName      
      
While @@FETCH_STATUS = 0       
BEGIN      
 DECLARE @ViewName nvarchar(255)       
 DECLARE @CleanTable nvarchar(255)      
 SELECT @ViewName = STUFF(@TableName,1,4,'')      
 --SELECT @CleanTable  = 'TRUNCATE TABLE WRKDQAPIUtilities.dbo.' + @TableName      
 SELECT @CleanTable  = 'DELETE FROM WRKDQAPIUtilities.dbo.' + @TableName + ' WHERE ExtractID = ''' + @ExtractID + ''''      
 SELECT @SQL = 'INSERT INTO WRKDQAPIUtilities.dbo.' + @TableName + ' SELECT * FROM WRKDQAPIUtilities.dbo.ImportJSONFILE' + @ViewName + ' WHERE ExtractID = ''' + @ExtractID + ''''      
 IF Object_id('WRKDQAPIUtilities.dbo.'+@TableName,'U') IS NOT NULL      
 BEGIN      
 SELECT @SQL      
  EXEC sp_executesql @CleanTable      
  EXEC sp_executesql @SQL      
  IF @InitializeTranslationTables = 'RESET'      
   BEGIN       
    --SELECT @CleanTable  = 'TRUNCATE TABLE WRKDQAPIUtilities.dbo.JSON' + @ViewName +';'      
    SELECT @CleanTable  = 'DELETE FROM WRKDQAPIUtilities.dbo.JSON' + @ViewName  + ' WHERE ExtractID = ''' + @ExtractID + '''' +';'      
    SELECT @SQL = 'INSERT INTO WRKDQAPIUtilities.dbo.JSON' + @ViewName + ' SELECT * FROM WRKDQAPIUtilities.dbo.TRANSLATIONS_REF' + @ViewName + ' WHERE ExtractID = ''' + @ExtractID + ''''      
    EXEC sp_executesql @CleanTable      
    EXEC sp_executesql @SQL      
   END      
  ELSE      
   IF @InitializeTranslationTables IS NOT NULL       
   BEGIN       
    --SELECT @CleanTable  = 'TRUNCATE TABLE WRKDQAPIUtilities.dbo.TRANSLATIONS_REF' + @ViewName +';'      
    SELECT @CleanTable  = 'TRUNCATE TABLE WRKDQAPIUtilities.dbo.TRANSLATIONS_REF' + @ViewName  + ' WHERE ExtractID = ''' + @ExtractID + '''' +';'      
    SELECT @SQL = 'INSERT INTO WRKDQAPIUtilities.dbo.TRANSLATIONS_REF' + @ViewName + ' SELECT * FROM WRKDQAPIUtilities.dbo.JSON' + @ViewName + ' WHERE ExtractID = ''' + @ExtractID + ''''      
    EXEC sp_executesql @CleanTable      
    EXEC sp_executesql @SQL      
   END      
      
 END      
      
 EXEC webKnowledgeTierExtract_GETAPIRESULTS_ID_Ins @ExtractID, @TableNameGETAPI      
      
 FETCH NEXT FROM Cur into @TableName      
END      
Close Cur;      
Deallocate Cur;      
      
/*Check what it does      
EXEC WRKDQAPIUtilities.dbo.API_MIG_JSON_ENFORCEMENTS_RUL_ID_INS @ExtractID      
EXEC WRKDQAPIUtilities.dbo.API_MIG_JSON_DATAQUALITYJOBS_ENF_ID_INS @ExtractID      
*/      
END 
GO
