	Where TABLE_NAME not like '%AGENTS%'--AND TABLE_NAME <> 'JSON_AGENTS'
	AND TABLE_NAME like '%JSON[_]'+@TableName
	OR TABLE_NAME like '%JSON[_]'+@TableName+'[_]%'
	ORDER BY TABLE_NAME
