	DECLARE @CleanTable nvarchar(255)
	SELECT @ViewName = STUFF(@TableName,1,4,'')
	--SELECT @CleanTable  = 'TRUNCATE TABLE WRKDQAPIUtilities.dbo.' + @TableName
	SELECT @CleanTable  = 'DELETE FROM WRKDQAPIUtilities.dbo.' + @TableName + ' WHERE ExtractID = ''' + @ExtractID + ''''
	SELECT @SQL = 'INSERT INTO WRKDQAPIUtilities.dbo.' + @TableName + ' SELECT * FROM WRKDQAPIUtilities.dbo.ImportJSONFILE' + @ViewName + ' WHERE ExtractID = ''' + @ExtractID + ''''
	IF Object_id('WRKDQAPIUtilities.dbo.'+@TableName,'U') IS NOT NULL
	BEGIN
